<script setup>
import { computed, ref } from 'vue'
import { DataAnalysis, Setting, Picture, List, Sunny, Moon, Refresh, ArrowRight, CircleCheck, Warning, VideoPause, DocumentCopy, Download, Connection } from '@element-plus/icons-vue'
import ConfigEditor from './components/ConfigEditor.vue'
import SystemMonitor from './components/SystemMonitor.vue'
import MetricChart from './components/MetricChart.vue'
import ImageMatrix from './components/ImageMatrix.vue'
import SamplerForm from './components/SamplerForm.vue'
import RunControls from './components/RunControls.vue'
import RunDetail from './components/RunDetail.vue'
import { useWorkbench } from './useWorkbench'
import { active, bytes, dateTime, downloadText, elapsed, numeric, stageName, statusName, statusType } from './api'

const { page, theme, info, schema, configs, configRecord, config, configDraftToken, evaluationConfig, evaluationOrigin, evaluationLoading, evaluationOptions, checkpoints, checkpointsLoading, jobConfig, jobs, selectedId, selectedJob, activeJobs, system, metrics, images, imagesTruncated, logs, logTrimmed, now, lastSuccess, initializing, loadingConfig, launching, stopping, saving, errors, errorList, saveDialog, revisionName, stopTarget, snapshot, snapshotDialog, snapshotLoading, options, dirty, newestMetric, configurationName, initialize, loadConfig, refreshConfigs, refreshCheckpoints, initializeEvaluation, poll, stageError, launch, confirmStop, saveRevision, viewSnapshot, loadSnapshot, useCache } = useWorkbench()
const nav = [
  { key: 'overview', label: 'Overview', secondary: '概览', icon: DataAnalysis, gem: 'iolite', description: '本地计算，清晰掌控。真实任务、训练指标与硬件状态。' },
  { key: 'configuration', label: 'Configuration', secondary: '配置', icon: Setting, gem: 'sapphire', description: '从预设开始，逐项调整。每次保存都是新版本，原文件保持不变。' },
  { key: 'evaluations', label: 'XY Evaluation', secondary: 'LoRA 评估', icon: Picture, gem: 'taaffeite', description: '独立评估多个已保存 LoRA 检查点。提示词为行，基座与检查点为列；不改变训练预览。' },
  { key: 'runs', label: 'Runs', secondary: '训练任务', icon: List, gem: 'amber', description: '训练流水线：Cache 缓存 → Train 训练。训练期预览随训练执行；历史检查点评估在独立工作区。' },
]
const navGroups = [
  { key: 'training', label: 'TRAINING · 训练', short: '训练', items: nav.filter(item => item.key !== 'evaluations') },
  { key: 'evaluation', label: 'EVALUATION · 评估', short: '评估', items: nav.filter(item => item.key === 'evaluations') },
]
const currentPage = computed(() => nav.find(item => item.key === page.value))
const configSearch = ref('')
const filteredConfigs = computed(() => configs.value.filter(item => `${item.name} ${item.path}`.toLowerCase().includes(configSearch.value.toLowerCase())))
const configGroups = computed(() => [
  { title: 'PRESETS · 内置预设', items: filteredConfigs.value.filter(item => item.id.startsWith('builtin:')) },
  { title: 'REVISIONS · 保存的版本', items: filteredConfigs.value.filter(item => !item.id.startsWith('builtin:')) },
])
const configAudit = ref(false)
const pipelineJobs = computed(() => jobs.value.filter(job => job.stage === 'cache' || job.stage === 'train'))
const evaluationJobs = computed(() => jobs.value.filter(job => job.stage === 'evaluation'))
const visibleJobs = computed(() => page.value === 'evaluations' ? evaluationJobs.value : page.value === 'runs' ? pipelineJobs.value : jobs.value)
const independence = '训练在独立后台进程运行。关闭浏览器或重启此页面不会停止任务；只有显式停止才会结束。'
const gpu = computed(() => system.value?.gpus?.[0])
function selectRun(id) { selectedId.value = id; page.value = jobs.value.find(job => job.id === id)?.stage === 'evaluation' ? 'evaluations' : 'runs' }
function beginSave() { revisionName.value = `${configRecord.value?.name?.replace(/-\d{8}T.*$/, '') || 'config'}-rev`; saveDialog.value = true }
</script>

<template>
  <div class="app-shell">
    <aside class="sidebar">
      <a class="brand" href="#overview" @click.prevent="page = 'overview'" aria-label="moss trainer 概览"><span class="brand-mark">m</span><div><strong>moss<span>_trainer</span></strong><small>LOCAL WORKBENCH</small></div><span class="live-dot" /></a>
      <div class="navigation-groups"><section v-for="group in navGroups" :key="group.key" :id="`nav-group-${group.key}`" class="navigation-group" :class="`navigation-group-${group.key}`" :aria-label="group.label"><h2 class="navigation-group-heading"><span>{{ group.label }}</span><small>{{ group.short }}</small></h2><nav class="workspace-nav" :aria-label="group.label"><button v-for="item in group.items" :key="item.key" :id="`nav-${item.key}`" :class="{ selected: page === item.key }" @click="page = item.key" :aria-current="page === item.key ? 'page' : undefined" :title="`${item.label} ${item.secondary}`"><el-icon><component :is="item.icon" /></el-icon><span>{{ item.label }}<small>{{ item.secondary }}</small></span><span class="nav-gem" :style="{ background: `var(--${item.gem})` }" /></button></nav></section></div>
      <div class="sidebar-processes"><div class="sidebar-label">ACTIVE PROCESSES <span>{{ activeJobs.length }}</span></div><p v-if="!activeJobs.length" class="sidebar-empty">暂无活动任务<br /><span>GPU ready when you are.</span></p><button v-for="job in activeJobs" :key="job.id" class="sidebar-process" @click="selectRun(job.id)"><span class="process-dot" :class="job.stage" /><div><strong>{{ job.name || job.id }}</strong><small>{{ statusName(job) }} · {{ elapsed(job, now) }}</small></div></button></div>
      <div class="sidebar-bottom"><div class="local-indicator"><el-icon><Connection /></el-icon><span>Local-only · 本机服务</span></div><p class="sidebar-device">{{ gpu?.name || '等待设备信息' }}</p><div class="sidebar-memory"><span>VRAM</span><code>{{ bytes(gpu?.memory_used_bytes) }} / {{ bytes(gpu?.memory_total_bytes) }}</code></div><el-progress v-if="gpu?.memory_percent != null" :percentage="Math.max(0, Math.min(100, gpu.memory_percent))" :show-text="false" :stroke-width="4" color="#A57EAE" /><button class="sidebar-theme" @click="theme = theme === 'dark' ? 'light' : 'dark'"><el-icon><component :is="theme === 'dark' ? Sunny : Moon" /></el-icon><span>{{ theme === 'dark' ? 'Light theme 浅色模式' : 'Dark theme 深色模式' }}</span></button></div>
    </aside>
    <div class="main-shell">
      <header class="topbar"><div class="breadcrumb">Workbench <el-icon><ArrowRight /></el-icon><strong>{{ currentPage.label }}</strong></div><div class="topbar-controls"><el-select id="job-select" v-model="selectedId" placeholder="选择当前工作区任务" filterable class="global-job-select" aria-label="当前查看的任务"><el-option v-for="job in visibleJobs" :key="job.id" :value="job.id" :label="`${job.name || job.id} · ${statusName(job)}`" /></el-select><span class="gpu-pill"><span class="live-dot" :class="{ offline: !system }" />GPU {{ numeric(gpu?.utilization_percent, 0) }}<span v-if="gpu?.utilization_percent != null">%</span></span><el-button id="theme-toggle" text circle :icon="theme === 'dark' ? Sunny : Moon" :aria-label="theme === 'dark' ? '切换浅色主题' : '切换深色主题'" @click="theme = theme === 'dark' ? 'light' : 'dark'" /></div></header>
      <main class="workspace" :class="`page-${page}`">
        <div class="page-heading"><div><div class="eyebrow">MOSS IMAGE / {{ currentPage.label.toUpperCase() }}</div><h1>{{ currentPage.label }} <span>{{ currentPage.secondary }}</span></h1><p>{{ currentPage.description }}</p></div><div class="page-heading-actions"><span class="connection-state" :class="{ problem: errors.jobs || errors.system }"><span class="live-dot" :class="{ offline: !lastSuccess || errors.jobs }" />{{ errors.jobs ? '连接异常' : initializing ? '正在连接' : lastSuccess ? '已连接 · 2s 更新' : '尚未连接' }}</span><el-button :icon="Refresh" :loading="initializing" @click="initialize" aria-label="刷新本地 API 连接">刷新</el-button></div></div>
        <div v-if="errorList.length" class="error-stack" role="region" aria-label="API 错误"><el-alert v-for="item in errorList" :key="item.key" :title="`${item.key} · ${item.message}`" type="error" show-icon @close="delete errors[item.key]" /></div>
        <el-alert v-if="page === 'overview' || page === 'runs'" class="independence-alert" :title="independence" type="info" show-icon :closable="false"><template #default>Independent process · 当前表单修改不会改变已启动任务。停止会丢失最近检查点之后的训练进度。</template></el-alert>

        <template v-if="page === 'overview'">
          <section aria-label="实时硬件监测"><SystemMonitor :system="system" /></section>
          <div class="overview-middle"><section class="overview-training"><el-card class="training-summary" shadow="never"><div class="summary-heading"><div><div class="eyebrow">SELECTED RUN · 当前任务</div><h2>{{ selectedJob?.name || '你的下一次训练，从这里开始' }}</h2></div><el-tag :type="statusType(selectedJob)">{{ statusName(selectedJob) }}</el-tag></div><div v-if="selectedJob?.stage === 'train'" class="summary-numbers"><div><span>OPTIMIZER STEP</span><strong>{{ numeric(newestMetric.step, 0) }}</strong></div><div><span>LATEST LOSS</span><strong>{{ numeric(newestMetric.loss, 5) }}</strong></div><div><span>SECONDS / STEP</span><strong>{{ numeric(newestMetric.seconds_per_step, 2) }}</strong></div></div><p v-else class="stage-summary-note">{{ selectedJob?.stage === 'cache' ? '缓存任务只记录缓存日志与真实输出路径；不产生训练曲线或预览。' : selectedJob?.stage === 'evaluation' ? '独立 XY 评估结果按提示词和检查点对齐，不混入训练历史。' : '加载配置后启动缓存与训练；训练预览在训练进程内执行。' }}</p><div class="summary-bottom"><span>{{ selectedJob ? `${stageName(selectedJob.stage)} · ${elapsed(selectedJob, now)}` : '未启动任务；不展示模拟指标' }}</span><el-button text type="primary" @click="selectedJob ? selectRun(selectedJob.id) : page = 'runs'">查看任务 <el-icon><ArrowRight /></el-icon></el-button></div></el-card><MetricChart v-if="selectedJob?.stage === 'train'" :rows="metrics.series" :fields="[{ key: 'loss', label: 'Training loss', color: '#D4920A' }]" title="Loss curve · 训练损失" :theme="theme" /></section>
            <el-card class="process-stack" shadow="never"><template #header><h2>Processes · 进程</h2><el-tag type="info">{{ activeJobs.length }} active</el-tag></template><div v-if="!activeJobs.length" class="process-empty"><el-icon><CircleCheck /></el-icon><h3>当前没有活动任务</h3><p>缓存、训练或独立评估启动后，后台进程会显示在这里。</p><el-button type="primary" plain @click="page = 'runs'">启动一个任务</el-button></div><article v-for="job in activeJobs" :key="job.id" class="active-process"><div class="active-process-heading"><span class="process-dot" :class="job.stage" /><h3>{{ stageName(job.stage) }}</h3><el-tag :type="statusType(job)" size="small">{{ statusName(job) }}</el-tag></div><p>{{ job.name }}</p><div class="job-facts"><span>PID {{ job.pid ?? '—' }}</span><span>{{ elapsed(job, now) }}</span></div><div class="inline-actions"><el-button text @click="selectRun(job.id)">查看任务</el-button><el-button type="danger" plain size="small" :disabled="job.status === 'stopping'" @click="stopTarget = job">{{ job.status === 'stopping' ? '停止中' : '停止' }}</el-button></div></article><div class="process-note"><el-icon><Connection /></el-icon><span>单 GPU 任务锁保护显存。当前活动任务完成前，不接受新 GPU 任务。</span></div></el-card></div>
          <el-card v-if="selectedJob?.stage === 'train' || selectedJob?.stage === 'evaluation'" shadow="never"><template #header><div><h2>{{ selectedJob.stage === 'train' ? 'Training previews · 训练期预览' : 'Evaluation results · 独立评估结果' }}</h2><p class="muted">{{ selectedJob.name }}</p></div><el-button text @click="selectRun(selectedJob.id)">查看任务详情 <el-icon><ArrowRight /></el-icon></el-button></template><ImageMatrix :mode="selectedJob.stage === 'train' ? 'training' : 'evaluation'" :images="images" :job="selectedJob" :config="jobConfig" :truncated="imagesTruncated" /></el-card>
          <div class="quick-actions"><button @click="page = 'configuration'"><el-icon><Setting /></el-icon><span><strong>Configure 配置</strong><small>训练参数与训练期预览</small></span><el-icon><ArrowRight /></el-icon></button><button @click="page = 'runs'"><el-icon><DataAnalysis /></el-icon><span><strong>Train 训练</strong><small>缓存 → 训练，实时日志</small></span><el-icon><ArrowRight /></el-icon></button><button @click="page = 'evaluations'"><el-icon><Picture /></el-icon><span><strong>XY Evaluation 评估</strong><small>独立草稿，多检查点矩阵</small></span><el-icon><ArrowRight /></el-icon></button></div>
        </template>

        <template v-else-if="page === 'configuration'">
          <div class="configuration-layout"><el-card class="config-library" shadow="never"><template #header><h2>Library · 配置库</h2><el-button text circle :icon="Refresh" @click="refreshConfigs" aria-label="刷新配置列表" /></template><el-input id="config-search" v-model="configSearch" placeholder="搜索预设 / 版本" clearable /><el-select id="config-select" :model-value="configRecord?.id" @update:model-value="loadConfig" placeholder="选择并加载配置" filterable :disabled="loadingConfig"><el-option v-for="entry in configs" :key="entry.id" :value="entry.id" :label="entry.name" /></el-select><div v-for="group in configGroups" :key="group.title" class="config-group"><div class="eyebrow">{{ group.title }}</div><p v-if="!group.items.length" class="muted">{{ configSearch ? '没有匹配项' : '尚无记录' }}</p><button v-for="entry in group.items" :key="entry.id" class="config-list-item" :class="{ selected: configRecord?.id === entry.id }" :data-config-id="entry.id" @click="loadConfig(entry.id)" :disabled="loadingConfig"><span class="config-file-icon"><DocumentCopy /></span><span><strong>{{ entry.name }}</strong><small>{{ entry.id.startsWith('builtin:') ? 'Preset · 只读原文件' : 'Revision · 独立保存' }}</small></span><el-icon v-if="configRecord?.id === entry.id"><CircleCheck /></el-icon></button></div><p class="library-note">加载与编辑只影响当前表单。保存始终创建新文件，不覆盖原始配置。</p></el-card>
            <div class="config-edit-pane"><el-card class="config-editor-card" shadow="never"><template #header><div><h2>{{ configurationName }}</h2><p class="config-source mono">{{ configRecord?.path || '请从配置库选择预设' }}</p></div><el-tag :type="dirty ? 'warning' : 'info'">{{ dirty ? 'Unsaved 未保存编辑' : 'Loaded 已载入' }}</el-tag></template><el-skeleton v-if="loadingConfig" :rows="5" animated /><ConfigEditor v-else-if="config" v-model="config" :schema="schema" :draft-token="configDraftToken" /><el-empty v-else description="没有加载配置 · 从左侧选择预设或刷新连接" /></el-card><div class="config-footer"><div><span class="preserve-label"><el-icon><CircleCheck /></el-icon>原文件永不覆盖</span><p>训练预览属于此配置；独立评估编辑不会修改本表单。</p></div><div class="inline-actions"><el-button :disabled="!config" @click="configAudit = true">查看配置</el-button><el-button id="save-revision" type="primary" :disabled="!config || loadingConfig" @click="beginSave">保存为新版本</el-button><el-button id="configure-to-runs" :disabled="!config" @click="page = 'runs'">启动训练任务 <el-icon><ArrowRight /></el-icon></el-button></div></div></div></div>
        </template>

        <template v-else-if="page === 'evaluations'">
          <SamplerForm v-model="evaluationConfig" :options="evaluationOptions" :config-name="evaluationOrigin" :schema="schema" :workspace-dir="info?.workspace_dir" :disabled-reason="stageError('evaluation')" :launching="launching" :checkpoints="checkpoints" :checkpoints-loading="checkpointsLoading" :initializing="evaluationLoading" :can-initialize="!!config" @launch="launch('evaluation')" @initialize="initializeEvaluation()" @checkpoint-config="initializeEvaluation(null, $event)" @refresh-checkpoints="refreshCheckpoints" />
          <el-card shadow="never"><template #header><h2>Evaluation history · 独立评估记录</h2><span class="muted">{{ evaluationJobs.length }} 个任务 · 包含历史独立采样</span></template><el-select id="evaluation-job-select" v-model="selectedId" filterable placeholder="选择独立评估任务"><el-option v-for="job in evaluationJobs" :key="job.id" :value="job.id" :label="`${job.name || job.id} · ${statusName(job)}`" /></el-select></el-card>
          <RunDetail v-if="selectedJob?.stage === 'evaluation'" :job="selectedJob" :job-config="jobConfig" :metrics="metrics" :images="images" :images-truncated="imagesTruncated" :logs="logs" :log-trimmed="logTrimmed" :theme="theme" :now="now" @stop="stopTarget = $event" @snapshot="viewSnapshot" />
        </template>

        <template v-else-if="page === 'runs'">
          <RunControls :options="options" :jobs="pipelineJobs" :config-name="configurationName" :launching="launching" :stage-error="stageError" :now="now" @launch="launch" @stop="stopTarget = $event" @select="selectedId = $event" />
          <el-card class="run-list-card" shadow="never"><template #header><h2>Training pipeline · 缓存与训练记录</h2><span class="muted">{{ pipelineJobs.length }} 个任务 · 独立评估见 XY Evaluation</span></template><el-table :data="pipelineJobs" row-key="id" highlight-current-row :current-row-key="selectedId" @row-click="row => selectedId = row.id" max-height="280" empty-text="暂无训练流水线任务 · 使用上方配置启动缓存 / 训练"><el-table-column label="任务" min-width="230"><template #default="{ row }"><button class="table-job-button" @click.stop="selectedId = row.id">{{ row.name || row.id }}</button></template></el-table-column><el-table-column label="阶段" width="140"><template #default="{ row }">{{ stageName(row.stage) }}</template></el-table-column><el-table-column label="状态" width="180"><template #default="{ row }"><el-tag :type="statusType(row)" size="small">{{ statusName(row) }}</el-tag></template></el-table-column><el-table-column label="PID" width="100"><template #default="{ row }"><code>{{ row.pid ?? '—' }}</code></template></el-table-column><el-table-column label="创建时间" min-width="180"><template #default="{ row }">{{ dateTime(row.created_at) }}</template></el-table-column></el-table></el-card>
          <RunDetail :job="selectedJob?.stage === 'evaluation' ? null : selectedJob" :job-config="jobConfig" :metrics="metrics" :images="images" :images-truncated="imagesTruncated" :logs="logs" :log-trimmed="logTrimmed" :theme="theme" :now="now" @stop="stopTarget = $event" @snapshot="viewSnapshot" @use-cache="useCache" @evaluate="initializeEvaluation" />
        </template>
        <footer class="workspace-footer"><span>moss_trainer · Local-first workbench</span><span>配置与输出保留在本地 · {{ info?.python ? 'Python backend' : '等待本地服务' }}</span></footer>
      </main>
    </div>
    <nav class="mobile-nav" aria-label="移动工作区分组"><section v-for="group in navGroups" :key="group.key" class="mobile-nav-group" :class="`mobile-nav-group-${group.key}`" :aria-label="group.label"><h2>{{ group.short }}</h2><div class="mobile-nav-items"><button v-for="item in group.items" :key="item.key" :class="{ selected: page === item.key }" @click="page = item.key" :aria-current="page === item.key ? 'page' : undefined"><el-icon><component :is="item.icon" /></el-icon><span>{{ item.secondary }}</span></button></div></section></nav>

    <el-dialog v-model="saveDialog" title="Save as new revision · 保存为新版本" width="min(560px, 94vw)" :close-on-click-modal="!saving" :close-on-press-escape="!saving"><el-alert title="原文件永不覆盖。此操作创建一个新的配置文件。" type="info" :closable="false" show-icon /><p class="dialog-source">基于 {{ configurationName }}</p><el-form label-position="top" @submit.prevent="saveRevision"><el-form-item label="Revision name · 版本名称" required><el-input id="revision-name" v-model="revisionName" placeholder="rev-04-lr1e4" maxlength="120" autofocus @keyup.enter="saveRevision" /></el-form-item></el-form><el-alert v-if="errors.save" :title="errors.save" type="error" :closable="false" /><template #footer><el-button @click="saveDialog = false" :disabled="saving">取消</el-button><el-button id="confirm-save-revision" type="primary" @click="saveRevision" :loading="saving" :disabled="!revisionName.trim()">保存新版本</el-button></template></el-dialog>
    <el-dialog :model-value="!!stopTarget" @update:model-value="value => { if (!value && !stopping) stopTarget = null }" title="Stop process · 确认停止后台任务" width="min(560px, 94vw)" :close-on-click-modal="false" :close-on-press-escape="!stopping"><div class="stop-warning"><el-icon><Warning /></el-icon><div><h3>停止 {{ stopTarget?.name }}？</h3><p>将终止此任务记录的后台进程及其子进程，不影响其他 Python 进程。</p><p><strong>训练最近检查点之后的进度会丢失。</strong>输出与已有检查点不会被删除；采样或缓存可能留下未完成的输出。</p></div></div><el-alert v-if="errors.stop" :title="errors.stop" type="error" :closable="false" /><template #footer><el-button id="cancel-stop" @click="stopTarget = null" :disabled="stopping">继续运行</el-button><el-button id="confirm-stop" type="danger" :icon="VideoPause" :loading="stopping" @click="confirmStop">确认停止</el-button></template></el-dialog>
    <el-drawer v-model="snapshotDialog" title="Task snapshot · 独立配置快照" size="min(760px, 94vw)"><el-skeleton v-if="snapshotLoading" :rows="8" animated /><template v-else-if="snapshot"><p class="mono field-hint">{{ snapshot.path }}</p><div class="inline-actions"><el-button id="load-job-snapshot" type="primary" @click="loadSnapshot">加载到配置表单</el-button><el-button :icon="Download" @click="downloadText('task-config.json', JSON.stringify(snapshot.config, null, 2))">下载副本</el-button></div><pre class="audit-view">{{ JSON.stringify(snapshot.config, null, 2) }}</pre></template><el-alert v-else-if="errors.snapshot" :title="errors.snapshot" type="error" :closable="false" /><el-empty v-else description="未读取到任务快照" /></el-drawer>
    <el-drawer v-model="configAudit" title="Current configuration · 当前表单只读预览" size="min(760px, 94vw)"><p class="muted">只读审阅，无需编辑 JSON 即可完成配置。</p><el-button :icon="Download" @click="downloadText('edited-config.json', JSON.stringify(config, null, 2))">下载当前副本</el-button><pre class="audit-view">{{ JSON.stringify(config, null, 2) }}</pre></el-drawer>
  </div>
</template>
